with up as (update public.artists a set bio=x.b from json_to_recordset('[{"s":"rafiki","b":"Rafiki is the DJ and producer alias of Sohail Arora, founder of the Mumbai events and artist management company Krunk and its label Krunk Kulture. Based in Mumbai, he plays acid, breaks, house and techno, has played Magnetic Fields and NH7 Weekender, and has released on Welt Discos, Permanent Vacation and Krunk Kulture."},{"s":"tapan-raj","b":"Tapan Raj is a Delhi producer and one half of the electronic duo Midival Punditz with Gaurav Raina. He has been part of Delhi''s underground electronic scene since 1997, playing across hip hop, house, breakbeats and garage."}]'::json) as x(s text,b text) where a.slug=x.s and (a.bio is null or length(trim(a.bio))<20) returning 1) select count(*) from up;